'use strict';
const fs = require('fs');
const path = require('path');
const cp = require('child_process');
const root = path.resolve(__dirname, '..');
const fail = message => { throw new Error(message); };
const metadata = JSON.parse(fs.readFileSync(path.join(root, 'assets/sample.json'), 'utf8'));
const packageJson = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8'));
if (!Array.isArray(metadata) || metadata.length !== 1) fail('sample.json must contain one gallery item');
const item = metadata[0];
if (item.creationDateTime !== '2026-08-30' || item.updateDateTime !== '2026-08-30') fail('gallery dates are incorrect');
if (item.thumbnails.length !== 0) fail('gallery thumbnails must be empty');
if (item.authors[0].gitHubAccount !== 'vystartasv' || item.authors[0].name !== 'Vilius Vystartas') fail('gallery author is incorrect');
if (packageJson.engines.node !== '>=22.14.0 <23.0.0') fail('Node engine range is incorrect');
if (packageJson.scripts.build !== 'gulp bundle --ship' || packageJson.scripts.package !== 'gulp package-solution --ship') fail('ship scripts are incorrect');
if (packageJson.dependencies['@microsoft/sp-core-library'] !== '1.23.2') fail('SPFx version is incorrect');
if (!item.references.some(reference => reference.url === 'https://learn.microsoft.com/sharepoint/dev/spfx/sharepoint-framework-overview' && reference.name && reference.description)) fail('Microsoft reference is incorrect');
const files = cp.execFileSync('git', ['-C', path.dirname(root), 'status', '--short', '--untracked-files=all'], { encoding: 'utf8' }).split('\n').filter(Boolean);
if (files.some(file => !file.includes('react-viva-connections-ace-reference/'))) fail('changes exist outside requested directory');
const secret = /(api[_-]?key|client[_-]?secret|access[_-]?token|password)\s*[:=]/i;
const walk = dir => fs.readdirSync(dir, { withFileTypes: true }).flatMap(entry => entry.isDirectory() && !['node_modules', 'lib', 'temp', 'solution'].includes(entry.name) ? walk(path.join(dir, entry.name)) : entry.isDirectory() ? [] : [path.join(dir, entry.name)]);
for (const file of walk(root)) if (!/package-lock\.json$/.test(file) && secret.test(fs.readFileSync(file, 'utf8'))) fail(`possible secret in ${path.relative(root, file)}`);
console.log('verify: scope, gallery metadata, SPFx version, and secret scan passed');
